import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a row-quad-per-block GEMV:
#   C[row] = sum_k A[row, k] * B[k]
#
# One CUDA block handles FOUR rows of A cooperatively (row-quad tiling).
# Compared to a row-pair scheme, this halves the number of CTAs launched
# for a given M, which in turn halves the number of times the (heavily
# reused) B vector is streamed from global memory across the whole grid,
# improving effective memory-bandwidth utilization since this kernel is
# bandwidth bound (A is huge: M x K x 4 bytes). Threads stride over K using
# vectorized 128-bit (float4) cp.async double-buffered loads for both A and
# B. A scalar tail loop handles any remaining elements when K is not a
# multiple of 4. Warp-level shuffle reduction followed by a block-level
# reduction (through shared memory) produces the four final scalars.
# Fallback TRIPLE/DOUBLE/SINGLE row paths handle the tail block when M is
# not an exact multiple of 4.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemv_kernel(
    .param .u64 gemv_kernel_param_0,
    .param .u64 gemv_kernel_param_1,
    .param .u64 gemv_kernel_param_2,
    .param .u32 gemv_kernel_param_3,
    .param .u32 gemv_kernel_param_4
)
{
    .reg .pred %p<70>;
    .reg .f32  %f<950>;
    .reg .b32  %r<900>;
    .reg .b64  %rd<600>;
    // Row-octet tiling: each CTA now cooperatively computes EIGHT rows of
    // A (instead of four), halving the number of CTAs launched for a given
    // M compared to the previous row-quad scheme. Since the B vector is
    // reused by every row processed within a CTA, halving the CTA count
    // halves the number of times B is re-streamed from global memory
    // across the whole grid, improving effective bandwidth utilization for
    // this bandwidth-bound GEMV kernel. Threads stride over K using
    // vectorized 128-bit (float4) global loads for both A and B, with a
    // scalar tail loop handling K % 4 remainders. Warp-level shuffle
    // reduction followed by a block-level reduction (through shared
    // memory) produces the eight final scalars. A generic per-row
    // fallback loop (TAIL) handles the tail CTA when M is not an exact
    // multiple of 8.
    .shared .align 4 .b8 warp_sums0[128];
    .shared .align 4 .b8 warp_sums1[128];
    .shared .align 4 .b8 warp_sums2[128];
    .shared .align 4 .b8 warp_sums3[128];
    .shared .align 4 .b8 warp_sums4[128];
    .shared .align 4 .b8 warp_sums5[128];
    .shared .align 4 .b8 warp_sums6[128];
    .shared .align 4 .b8 warp_sums7[128];
    ld.param.u64 %rd1, [gemv_kernel_param_0];   // A ptr
    ld.param.u64 %rd2, [gemv_kernel_param_1];   // B ptr
    ld.param.u64 %rd3, [gemv_kernel_param_2];   // C ptr
    ld.param.u32 %r1,  [gemv_kernel_param_3];   // M
    ld.param.u32 %r2,  [gemv_kernel_param_4];   // K
    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;
    mov.u32 %r3, %ctaid.x;                 // block id
    shl.b32 %r30, %r3, 3;                  // row0 = blockIdx.x * 8
    setp.ge.s32 %p1, %r30, %r1;
    @%p1 bra DONE;
    add.s32 %r31, %r30, 7;                 // row0 + 7 (last row of full octet)
    setp.lt.s32 %p2, %r31, %r1;            // p2 = all 8 rows valid
    @%p2 bra OCT;
    bra TAIL;
OCT:
    mov.u32 %r500, %tid.x;
    mov.u32 %r501, %ntid.x;
    add.s32 %r510, %r30, 1;
    add.s32 %r511, %r30, 2;
    add.s32 %r512, %r30, 3;
    add.s32 %r513, %r30, 4;
    add.s32 %r514, %r30, 5;
    add.s32 %r515, %r30, 6;
    add.s32 %r516, %r30, 7;
    mul.wide.u32 %rd500, %r30, %r2;
    shl.b64 %rd501, %rd500, 2;
    add.s64 %rd502, %rd4, %rd501;          // A0 base
    mul.wide.u32 %rd503, %r510, %r2;
    shl.b64 %rd504, %rd503, 2;
    add.s64 %rd505, %rd4, %rd504;          // A1 base
    mul.wide.u32 %rd506, %r511, %r2;
    shl.b64 %rd507, %rd506, 2;
    add.s64 %rd508, %rd4, %rd507;          // A2 base
    mul.wide.u32 %rd509, %r512, %r2;
    shl.b64 %rd510, %rd509, 2;
    add.s64 %rd511, %rd4, %rd510;          // A3 base
    mul.wide.u32 %rd512, %r513, %r2;
    shl.b64 %rd513, %rd512, 2;
    add.s64 %rd514, %rd4, %rd513;          // A4 base
    mul.wide.u32 %rd515, %r514, %r2;
    shl.b64 %rd516, %rd515, 2;
    add.s64 %rd517, %rd4, %rd516;          // A5 base
    mul.wide.u32 %rd518, %r515, %r2;
    shl.b64 %rd519, %rd518, 2;
    add.s64 %rd520, %rd4, %rd519;          // A6 base
    mul.wide.u32 %rd521, %r516, %r2;
    shl.b64 %rd522, %rd521, 2;
    add.s64 %rd523, %rd4, %rd522;          // A7 base
    mov.f32 %f500, 0f00000000;
    mov.f32 %f501, 0f00000000;
    mov.f32 %f502, 0f00000000;
    mov.f32 %f503, 0f00000000;
    mov.f32 %f504, 0f00000000;
    mov.f32 %f505, 0f00000000;
    mov.f32 %f506, 0f00000000;
    mov.f32 %f507, 0f00000000;
    shr.u32 %r520, %r2, 2;                 // vec_K
    mov.u32 %r700, %ctaid.y;               // split id s
    mov.u32 %r701, %nctaid.y;              // number of splits S
    add.s32 %r702, %r520, %r701;
    sub.s32 %r702, %r702, 1;
    div.u32 %r703, %r702, %r701;           // chunk = ceil(vec_K/S)
    mul.lo.s32 %r704, %r700, %r703;        // start_vec
    add.s32 %r705, %r704, %r703;
    min.s32 %r706, %r705, %r520;           // end_vec
    add.s32 %r707, %r700, 1;
    setp.eq.s32 %p20, %r707, %r701;        // last split flag
    setp.ne.s32 %p21, %r707, %r701;        // not-last-split flag
    add.s32 %r521, %r704, %r500;           // vi = start_vec + tid
OCT_VLOOP:
    setp.ge.s32 %p10, %r521, %r706;
    @%p10 bra OCT_VLOOP_END;
    mul.wide.u32 %rd530, %r521, 16;
    add.s64 %rd531, %rd502, %rd530;
    add.s64 %rd532, %rd505, %rd530;
    add.s64 %rd533, %rd508, %rd530;
    add.s64 %rd534, %rd511, %rd530;
    add.s64 %rd535, %rd514, %rd530;
    add.s64 %rd536, %rd517, %rd530;
    add.s64 %rd537, %rd520, %rd530;
    add.s64 %rd538, %rd523, %rd530;
    add.s64 %rd539, %rd5,  %rd530;
    ld.global.v4.f32 {%f550,%f551,%f552,%f553}, [%rd531];
    ld.global.v4.f32 {%f554,%f555,%f556,%f557}, [%rd532];
    ld.global.v4.f32 {%f558,%f559,%f560,%f561}, [%rd533];
    ld.global.v4.f32 {%f562,%f563,%f564,%f565}, [%rd534];
    ld.global.v4.f32 {%f566,%f567,%f568,%f569}, [%rd535];
    ld.global.v4.f32 {%f570,%f571,%f572,%f573}, [%rd536];
    ld.global.v4.f32 {%f574,%f575,%f576,%f577}, [%rd537];
    ld.global.v4.f32 {%f578,%f579,%f580,%f581}, [%rd538];
    ld.global.v4.f32 {%f582,%f583,%f584,%f585}, [%rd539];
    fma.rn.f32 %f500, %f550, %f582, %f500;
    fma.rn.f32 %f500, %f551, %f583, %f500;
    fma.rn.f32 %f500, %f552, %f584, %f500;
    fma.rn.f32 %f500, %f553, %f585, %f500;
    fma.rn.f32 %f501, %f554, %f582, %f501;
    fma.rn.f32 %f501, %f555, %f583, %f501;
    fma.rn.f32 %f501, %f556, %f584, %f501;
    fma.rn.f32 %f501, %f557, %f585, %f501;
    fma.rn.f32 %f502, %f558, %f582, %f502;
    fma.rn.f32 %f502, %f559, %f583, %f502;
    fma.rn.f32 %f502, %f560, %f584, %f502;
    fma.rn.f32 %f502, %f561, %f585, %f502;
    fma.rn.f32 %f503, %f562, %f582, %f503;
    fma.rn.f32 %f503, %f563, %f583, %f503;
    fma.rn.f32 %f503, %f564, %f584, %f503;
    fma.rn.f32 %f503, %f565, %f585, %f503;
    fma.rn.f32 %f504, %f566, %f582, %f504;
    fma.rn.f32 %f504, %f567, %f583, %f504;
    fma.rn.f32 %f504, %f568, %f584, %f504;
    fma.rn.f32 %f504, %f569, %f585, %f504;
    fma.rn.f32 %f505, %f570, %f582, %f505;
    fma.rn.f32 %f505, %f571, %f583, %f505;
    fma.rn.f32 %f505, %f572, %f584, %f505;
    fma.rn.f32 %f505, %f573, %f585, %f505;
    fma.rn.f32 %f506, %f574, %f582, %f506;
    fma.rn.f32 %f506, %f575, %f583, %f506;
    fma.rn.f32 %f506, %f576, %f584, %f506;
    fma.rn.f32 %f506, %f577, %f585, %f506;
    fma.rn.f32 %f507, %f578, %f582, %f507;
    fma.rn.f32 %f507, %f579, %f583, %f507;
    fma.rn.f32 %f507, %f580, %f584, %f507;
    fma.rn.f32 %f507, %f581, %f585, %f507;
    add.s32 %r521, %r521, %r501;
    bra OCT_VLOOP;
OCT_VLOOP_END:
    mul.lo.s32 %r560, %r520, 4;
    add.s32 %r561, %r560, %r500;
    @%p21 bra OCT_TLOOP_END;
OCT_TLOOP:
    setp.ge.s32 %p11, %r561, %r2;
    @%p11 bra OCT_TLOOP_END;
    mul.wide.u32 %rd540, %r561, 4;
    add.s64 %rd541, %rd502, %rd540;
    add.s64 %rd542, %rd505, %rd540;
    add.s64 %rd543, %rd508, %rd540;
    add.s64 %rd544, %rd511, %rd540;
    add.s64 %rd545, %rd514, %rd540;
    add.s64 %rd546, %rd517, %rd540;
    add.s64 %rd547, %rd520, %rd540;
    add.s64 %rd548, %rd523, %rd540;
    add.s64 %rd549, %rd5,  %rd540;
    ld.global.f32 %f590, [%rd541];
    ld.global.f32 %f591, [%rd542];
    ld.global.f32 %f592, [%rd543];
    ld.global.f32 %f593, [%rd544];
    ld.global.f32 %f594, [%rd545];
    ld.global.f32 %f595, [%rd546];
    ld.global.f32 %f596, [%rd547];
    ld.global.f32 %f597, [%rd548];
    ld.global.f32 %f598, [%rd549];
    fma.rn.f32 %f500, %f590, %f598, %f500;
    fma.rn.f32 %f501, %f591, %f598, %f501;
    fma.rn.f32 %f502, %f592, %f598, %f502;
    fma.rn.f32 %f503, %f593, %f598, %f503;
    fma.rn.f32 %f504, %f594, %f598, %f504;
    fma.rn.f32 %f505, %f595, %f598, %f505;
    fma.rn.f32 %f506, %f596, %f598, %f506;
    fma.rn.f32 %f507, %f597, %f598, %f507;
    add.s32 %r561, %r561, %r501;
    bra OCT_TLOOP;
OCT_TLOOP_END:
    mov.b32 %r600, %f500;
    shfl.sync.down.b32 %r601|%p12, %r600, 16, 31, -1;
    mov.b32 %f600, %r601;
    add.f32 %f500, %f500, %f600;
    mov.b32 %r600, %f500;
    shfl.sync.down.b32 %r601|%p12, %r600, 8, 31, -1;
    mov.b32 %f600, %r601;
    add.f32 %f500, %f500, %f600;
    mov.b32 %r600, %f500;
    shfl.sync.down.b32 %r601|%p12, %r600, 4, 31, -1;
    mov.b32 %f600, %r601;
    add.f32 %f500, %f500, %f600;
    mov.b32 %r600, %f500;
    shfl.sync.down.b32 %r601|%p12, %r600, 2, 31, -1;
    mov.b32 %f600, %r601;
    add.f32 %f500, %f500, %f600;
