    mov.b32 %r600, %f501;
    shfl.sync.down.b32 %r601|%p12, %r600, 4, 31, -1;
    mov.b32 %f600, %r601;
    add.f32 %f501, %f501, %f600;
    mov.b32 %r600, %f501;
    shfl.sync.down.b32 %r601|%p12, %r600, 2, 31, -1;
    mov.b32 %f600, %r601;
